#include <stdio.h>
#include <stdint.h>

// Hemos de añadir esta linea
extern void initialise_monitor_handles(void);

int main(void) {
	// Hemos de añadir esta linea
	initialise_monitor_handles();

    uint32_t *pClkCtrlReg = (uint32_t*)0x40023830; /* Puntero del RCC */
    uint32_t *pPortCModReg = (uint32_t*)0x40020800; /* Puntero del mode register */
    uint32_t *pPortCOutDatReg = (uint32_t*)0x40020814; /* Puntero del output data register */

    /* Activar reloj del periférico GPIOC en AHB1ENR  */

    *pClkCtrlReg |= 0x04;

    /* Poner el PIN en modo output */

    /* a. Limpiamos los bits 27 y 26 poniendolos a 0 */
    *pPortCModReg &= 0xF3FFFFFF;
    /* b. Seteamos el bit 27 a 1 */
    *pPortCModReg |= 0x04000000;

    /* Setear el bit 13 del output data register en 0 (Encender)*/
    *pPortCOutDatReg &= ~0x2000;

    /* Setear el bit 13 del output data register en 1 (apagar) */
    *pPortCOutDatReg |= 0x2000;

    while(1);
}
